describe("doctests of sympy.parsing.latex", () => {
  it("expr", () => {
    expect(sympyStr(parseLatex('\\frac {1 + \\sqrt {\\a}} {\\b}'))).toBe('(sqrt(a) + 1)/b');
  });
  // no value
  //   expr.evalf(4, subs=dict(a=5, b=2))
  //   => 1.618
  it.todo("expr.evalf(4, subs=dict(a=5, b=2))");
  // no value
  //   func.evalf(subs={"alpha": 2})
  //   => 0.693147180559945
  it.todo("func.evalf(subs={\"alpha\": 2})");
});

